const f = $input.first().json;
const dur = Number(f['Duração (segundos)']) || 25;
const palavras = Math.round(dur * 2.6);
const visuais = 'coracao, estrela, sol, lua, terra, gota, raio, relogio, cerebro, olho, lampada, foguete, polvo, numero, pergunta, exclamacao';
const system = [
  'Voce cria roteiros de videos curtos de curiosidade em portugues do Brasil.',
  'Responda SOMENTE com um objeto JSON valido, sem texto antes ou depois.',
  'O objeto tem os campos: titulo (texto curto) e cenas (lista).',
  'Cada cena tem: texto (a frase falada), visual, emocao e, so quando visual for numero, o campo numero (texto curto como 3 ou 1000).',
  'Regras: a primeira cena e um gancho que surpreende; a ultima e uma frase curta de efeito; de 4 a 7 cenas; cada cena com 1 a 2 frases de ate 16 palavras.',
  'visual deve ser exatamente um destes: ' + visuais + '. Escolha o que ilustra melhor a frase.',
  'emocao deve ser exatamente um destes: curioso, surpreso, feliz, pensativo.',
  'Use so fatos verdadeiros e verificaveis. Escreva numeros por extenso no campo texto. Nao use emojis nem simbolos.'
].join(' ');
const user = 'Tema: ' + f['Tema'] + '. Total aproximado de ' + palavras + ' palavras na soma dos textos das cenas.';
return [{ json: { body: { model: 'llama-3.3-70b-versatile', temperature: 0.7, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } }];

let raw = ($input.first().json.choices[0].message.content || '').trim();
raw = raw.replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '');
const cfg = JSON.parse(raw);
const ok = ['coracao','estrela','sol','lua','terra','gota','raio','relogio','cerebro','olho','lampada','foguete','polvo','numero','pergunta','exclamacao'];
const emo = ['curioso','surpreso','feliz','pensativo'];
if (!Array.isArray(cfg.cenas) || cfg.cenas.length < 2) throw new Error('O modelo nao devolveu as cenas esperadas.');
cfg.cenas = cfg.cenas.map(c => ({
  texto: String(c.texto || '').trim(),
  visual: ok.includes(c.visual) ? c.visual : 'pergunta',
  emocao: emo.includes(c.emocao) ? c.emocao : 'curioso',
  ...(c.numero ? { numero: String(c.numero) } : {})
})).filter(c => c.texto);
const slug = 'short-' + Date.now();
const narracao = cfg.cenas.map(c => c.texto).join(' ');
return [{ json: {
  slug, dir: '/data/shorts/' + slug, titulo: cfg.titulo || slug,
  cenasB64: Buffer.from(JSON.stringify(cfg), 'utf8').toString('base64'),
  narracaoB64: Buffer.from(narracao, 'utf8').toString('base64')
} }];
